import js from '@eslint/js';
import tseslint from 'typescript-eslint';
import reactPlugin from 'eslint-plugin-react';
import reactHooksPlugin from 'eslint-plugin-react-hooks';
import reactRefreshPlugin from 'eslint-plugin-react-refresh';
import prettier from 'eslint-config-prettier';

export default tseslint.config(
  // Global ignores
  {
    ignores: [
      '**/dist/**',
      '**/build/**',
      '**/node_modules/**',
      '**/.next/**',
      '**/coverage/**',
      'client/dist/**',
      '**.databricks/**',
      'shared/appkit-types/**', // generated by typegen — not linted
    ],
  },

  // Base JavaScript config
  js.configs.recommended,

  // TypeScript config for all TS files
  ...tseslint.configs.recommendedTypeChecked,
  {
    languageOptions: {
      parserOptions: {
        projectService: true,
        tsconfigRootDir: import.meta.dirname,
      },
    },
  },

  // React config for client-side files
  {
    files: ['client/**/*.{ts,tsx}', '**/*.tsx'],
    plugins: {
      react: reactPlugin,
      'react-hooks': reactHooksPlugin,
      'react-refresh': reactRefreshPlugin,
    },
    settings: {
      react: {
        version: 'detect',
      },
    },
    rules: {
      ...reactPlugin.configs.recommended.rules,
      ...reactPlugin.configs['jsx-runtime'].rules,
      ...reactHooksPlugin.configs.recommended.rules,
      'react-refresh/only-export-components': ['warn', { allowConstantExport: true }],
      'react/prop-types': 'off', // Using TypeScript for prop validation
      'react/no-array-index-key': 'warn',
      // Close the chart hole: appkit-ui charts with a `queryKey` prop fetch internally
      // and bypass useMigrationQuery (no catalog/refresh_token injection). Charts must
      // receive `data` from a useMigrationQuery call in the page instead.
      'react/forbid-component-props': [
        'error',
        {
          forbid: [
            {
              propName: 'queryKey',
              message:
                'Do not pass queryKey to a chart — it fetches internally and bypasses useMigrationQuery (catalog + refresh_token injection). Fetch with useMigrationQuery in the page and pass `data` to the chart.',
            },
          ],
        },
      ],
    },
  },

  // Node.js specific config for server files
  {
    files: ['server/**/*.ts', '*.config.{js,ts}'],
    rules: {
      '@typescript-eslint/no-var-requires': 'off',
    },
  },

  // Disable type-checking for JS config files and standalone config files
  {
    files: ['**/*.js', '*.config.ts', '**/*.config.ts'],
    ...tseslint.configs.disableTypeChecked,
  },

  // Enforcement: pages must read via useMigrationQuery, never useAnalyticsQuery directly.
  // This makes the catalog/refresh_token injection un-bypassable rather than a convention.
  {
    files: ['client/**/*.{ts,tsx}'],
    rules: {
      'no-restricted-imports': [
        'error',
        {
          paths: [
            {
              name: '@databricks/appkit-ui/react',
              importNames: ['useAnalyticsQuery'],
              message:
                'Do not call useAnalyticsQuery directly. Use useMigrationQuery (client/src/hooks/useMigrationQuery.ts) — it injects catalog + refresh_token and memoizes params. Only that hook may import useAnalyticsQuery.',
            },
          ],
        },
      ],
    },
  },
  // The single file allowed to wrap useAnalyticsQuery.
  {
    files: ['client/src/hooks/useMigrationQuery.ts'],
    rules: {
      'no-restricted-imports': 'off',
    },
  },

  // Prettier config (must be last to override other formatting rules)
  prettier,

  // Custom rules
  {
    rules: {
      '@typescript-eslint/no-unused-vars': [
        'error',
        {
          argsIgnorePattern: '^_',
          varsIgnorePattern: '^_',
        },
      ],
      '@typescript-eslint/no-explicit-any': 'warn',
    },
  }
);
